pub fn write_stdout(vm: &mut Vm, s: &str) {
    let _ = vm;
    let out = std::io::stdout();
    let mut l = out.lock();
    let _ = l.write_all(s.as_bytes());
    let _ = l.flush();
}

pub fn write_stdout_bytes(b: &[u8]) {
    let out = std::io::stdout();
    let mut l = out.lock();
    let _ = l.write_all(b);
