fn is_ws(c: char) -> bool {
    match c {
        '\t' | '\u{b}' | '\u{c}' | ' ' | '\u{a0}' | '\u{feff}' => true,
        _ if (c as u32) < 128 => false,
        _ => unicode::is_js_whitespace(c as u32),
