                    return first.parse().unwrap_or(0);
                }
            }
        }
    }
    0
}

fn parent_pid() -> u32 {
    if let Ok(s) = std::fs::read_to_string("/proc/self/stat") {
        let after = s.rsplit(')').next().unwrap_or("");
        let parts: Vec<&str> = after.split_whitespace().collect();
        if parts.len() > 1 {
            return parts[1].parse().unwrap_or(0);
        }
    }
    0
}

