fn error_with(vm: &mut Vm, kind: &str, msg: &str, props: &[(&str, &str)]) -> Value {
    let e = vm.make_error(kind, msg);
    if let Value::Obj(o) = &e {
        for (k, v) in props {
            o.set_prop(key(k), Value::str(v), WEC);
        }
    }
    e
}

fn plain_err(vm: &mut Vm, msg: &str) -> Value {
    vm.make_error("Error", msg)
}

